// --- Navigation -------------------------------------------------------------

type navItem struct {
	Key, Href, Label, Icon string
	Need                   Perm
}

var navItems = []navItem{
	{"results", "/", "Results", "trophy", PermNone},
	{"sell", "/sell", "Sell", "ticket", PermSell},
	{"sales", "/tickets", "Sales", "chart", PermNone},
	{"approvals", "/approvals", "Approvals", "inbox", PermUsers},
	{"users", "/users", "Users", "user", PermUsers},
	{"agents", "/agents", "Agents", "shop", PermAgents},
	{"prices", "/settings", "Prices", "tag", PermPrices},
	{"activity", "/activity", "Activity", "pulse", PermActivity},
	{"setup", "/setup/app", "Setup", "gear", PermSetup},
}

// navFor is the navigation for u's role. Sellers can't approve, so their
// Approvals page is "Requests": what they asked for.
func navFor(u User) []navItem {
	var out []navItem
	for _, it := range navItems {
		if it.Need != PermNone && !u.Can(it.Need) {
			continue
		}
		if it.Key == "approvals" && !u.Can(PermApprove) {
			it.Label = "Requests"
		}
		out = append(out, it)
	}
	return out
}

// splitNav keeps the first n items in view and puts the rest under
// "More" when there are more than max.
func splitNav(items []navItem, max, n int) ([]navItem, []navItem) {
	if len(items) <= max {
		return items, nil
	}
	return items[:n], items[n:]
}

func navHas(items []navItem, key string) bool {
	for _, it := range items {
		if it.Key == key {
			return true
		}
	}
	return false
}

