// shareData is what static/share.js needs to draw the receipt image.
type shareData struct {
	Serial   string      `json:"serial"`
	DrawDate string      `json:"drawDate"`
	Agent    string      `json:"agent"`
	Seller   string      `json:"seller"`
	Buyer    string      `json:"buyer"`
	Sold     string      `json:"sold"`
	Total    string      `json:"total"`
	Link     string      `json:"link"`
	Lines    []shareLine `json:"lines"`
	Brand    shareBrand  `json:"brand"`
}

// shareBrand is the app's name, logo and colours for the share images.
type shareBrand struct {
	Name    string `json:"name"`
	Tagline string `json:"tagline"`
	Logo    string `json:"logo,omitempty"`
	Color   string `json:"color"`
	Accent  string `json:"accent"`
	Note    string `json:"note"`
	Contact string `json:"contact"`
	Slug    string `json:"slug"`
}

func newShareBrand() shareBrand {
	b := brand()
	sb := shareBrand{Name: b.Name, Tagline: b.Tagline, Color: b.Color, Accent: b.Accent,
		Note: b.ReceiptNote, Contact: b.Contact(), Slug: b.FileSlug()}
	if b.HasLogo() {
		sb.Logo = b.LogoURL()
	}
	return sb
}

type shareLine struct {
	Number string `json:"number"`
	Game   string `json:"game"`
	Qty    string `json:"qty"`
	Price  string `json:"price"`
	Amount string `json:"amount"`
}

func newShareData(t Ticket, link string) shareData {
	d := shareData{Serial: t.Serial, DrawDate: t.DrawDate, Seller: t.SellerName, Buyer: t.Buyer,
		Sold: t.SoldAt.Format("2 Jan 2006, 15:04"), Total: t.Total().String(), Link: link, Brand: newShareBrand()}
	if t.AgentCode != "" {
		d.Agent = t.AgentCode + ", " + t.Agent
	}
	for _, l := range t.Lines {
		d.Lines = append(d.Lines, shareLine{l.Number, string(l.Game), fmt.Sprint(l.Qty), l.Price.String(), l.Amount().String()})
	}
	return d
}

