// --- Sales ------------------------------------------------------------------

// SalesOptions holds the filter choices; empty for sellers.
type SalesOptions struct {
	Agents     []Agent
	SellerName string // set when the list is narrowed to one seller
}

type AgentTotal struct {
	Code    string
	Name    string
	Tickets int
	Total   Cents
}

// topAgents is how many agents the "By agent" panel lists.
const topAgents = 8

func salesURL(f TicketFilter, agent string) templ.SafeURL {
	q := url.Values{}
	if f.DrawDate != "" {
		q.Set("date", f.DrawDate)
	}
	q.Set("agent", agent)
	return templ.SafeURL("/tickets?" + q.Encode())
}

// withoutSeller is the current sales URL minus the seller filter.
func withoutSeller(p Pager) templ.SafeURL {
	p2 := p
	p2.Params = url.Values{}
	for k, v := range p.Params {
		if k != "seller" {
			p2.Params[k] = v
		}
	}
	return p2.URL(1)
}

// share is a bar width for one part of a total.
func share(part, total Cents) templ.SafeCSS {
	if total <= 0 {
		return "width:0%"
	}
	return templ.SafeCSS(fmt.Sprintf("width:%.1f%%", float64(part)*100/float64(total)))
}

func filtered(f TicketFilter) bool {
	return f.DrawDate != "" || f.AgentCode != "" || f.Seller != "" || !f.Search.Empty()
}

